/// A last-in, first-out stack of values.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    /// Creates a new, empty stack.
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    /// Pushes `value` onto the top of the stack.
    pub fn push(&mut self, value: T) {
        self.items.push(value);
    }

    /// Removes and returns the top value, or `None` if the stack is empty.
    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    /// Returns `true` if the stack holds no values.
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

impl<T> Default for Stack<T> {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_add() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn new_stack_is_empty() {
        let stack: Stack<i32> = Stack::new();
        assert!(stack.is_empty());
    }

    #[test]
    fn push_makes_stack_non_empty() {
        let mut stack = Stack::new();
        stack.push(1);
        assert!(!stack.is_empty());
    }

    #[test]
    fn pop_returns_values_in_lifo_order() {
        let mut stack = Stack::new();
        stack.push(1);
        stack.push(2);
        stack.push(3);

        assert_eq!(stack.pop(), Some(3));
        assert_eq!(stack.pop(), Some(2));
        assert_eq!(stack.pop(), Some(1));
    }

    #[test]
    fn pop_on_empty_stack_returns_none() {
        let mut stack: Stack<i32> = Stack::new();
        assert_eq!(stack.pop(), None);
        assert!(stack.is_empty());
    }

    #[test]
    fn is_empty_after_popping_all_values() {
        let mut stack = Stack::new();
        stack.push(42);
        assert!(!stack.is_empty());

        assert_eq!(stack.pop(), Some(42));
        assert!(stack.is_empty());
    }

    #[test]
    fn works_with_non_copy_types() {
        let mut stack = Stack::new();
        stack.push(String::from("a"));
        stack.push(String::from("b"));

        assert_eq!(stack.pop(), Some(String::from("b")));
        assert_eq!(stack.pop(), Some(String::from("a")));
        assert_eq!(stack.pop(), None);
    }

    #[test]
    fn default_matches_new() {
        let from_default: Stack<u8> = Stack::default();
        let from_new: Stack<u8> = Stack::new();
        assert_eq!(from_default, from_new);
        assert!(from_default.is_empty());
    }
}"}
